function gersh(A)
    n = size(A, 1);
    th = linspace(0, 2*pi, 300);
    hold on;
    for i = 1:n
        c = A(i, i);
        r = sum(abs(A(i, :))) - abs(c);
        h1 = plot(real(c) + r*cos(th), imag(c) + r*sin(th), 'b-', 'LineWidth', 1.2);
    end
    ev = eig(A);
    h2 = plot(real(ev), imag(ev), 'r*', 'MarkerSize', 8, 'LineWidth', 1.2);
    axis equal; grid on;
    xlabel('Re(z)'); ylabel('Im(z)');
    legend([h1, h2], {'Gerschgorin 行圆盘', '特征值'});
end

function gersh_row_col(A)
    n = size(A, 1);
    th = linspace(0, 2*pi, 300);
    hold on;
    h1 = []; h2 = [];
    for i = 1:n
        c = A(i, i);
        rr = sum(abs(A(i, :))) - abs(c);
        rc = sum(abs(A(:, i))) - abs(c);
        h1 = plot(real(c) + rr*cos(th), imag(c) + rr*sin(th), 'b-', 'LineWidth', 1.2);
        h2 = plot(real(c) + rc*cos(th), imag(c) + rc*sin(th), 'g--', 'LineWidth', 1.2);
    end
    ev = eig(A);
    h3 = plot(real(ev), imag(ev), 'r*', 'MarkerSize', 8, 'LineWidth', 1.2);
    axis equal; grid on;
    xlabel('Re(z)'); ylabel('Im(z)');
    legend([h1, h2, h3], {'行圆盘', '列圆盘', '特征值'});
end
